import {Bird,Egg,Wallet,Gift,Banknote,User,Home,ShoppingBag,Receipt,LogOut,Menu,X,RefreshCw,Settings,Users,CreditCard,Check,Clock3,ChevronRight,Pencil,Plus,ShieldCheck,AlertCircle} from 'lucide-react';

const money=n=>`Rs ${Number(n||0).toLocaleString()}`;
const err=e=>e?.message||e?.error_description||'Something went wrong.';
const rows=x=>Array.isArray(x)?x:[];
async function call(p){const {data,error}=await p;if(error)throw error;return data}

async function farmSnapshot(){
  try{
    const data=await call(supabase.rpc('get_customer_farm_snapshot'));
    return data||{wallet:{balance:0,total_eggs:0},ducks:[]};
  }catch(primary){
    // Resilient fallback: even if the snapshot RPC is temporarily unavailable,
    // the customer can still see the server records directly.
    const {data:{user}}=await supabase.auth.getUser();
    if(!user) throw primary;
    await call(supabase.rpc('claim_due_eggs'));
    await call(supabase.rpc('claim_due_referral_eggs'));
    const [wallet,ducks]=await Promise.all([
      call(supabase.from('egg_wallets').select('*').eq('user_id',user.id).maybeSingle()),
      call(supabase.from('duck_purchases').select('*,ducks(*)').eq('user_id',user.id).order('created_at',{ascending:false}))
    ]);
    return {wallet:wallet||{balance:0,total_eggs:0},ducks:rows(ducks),server_time:new Date().toISOString()};
  }
}
function Btn({children,secondary=false,...p}){return <button className={`btn ${secondary?'secondary':''}`} {...p}>{children}</button>}
function Card({children,className=''}){return <section className={`card ${className}`}>{children}</section>}
function Field({label,...p}){return <label className="field"><span>{label}</span><input {...p}/></label>}
function Select({label,children,...p}){return <label className="field"><span>{label}</span><select {...p}>{children}</select></label>}
function Notice({children,type='info',onClose}){return <div className={`notice ${type}`}><span>{children}</span>{onClose&&<button onClick={onClose}><X size={16}/></button>}</div>}
function Title({eyebrow,title,desc,action}){return <div className="title"><div><small>{eyebrow}</small><h1>{title}</h1><p>{desc}</p></div>{action}</div>}

