const DUCK_LOGO_DATA="data:image/jpeg;base64,";
function DuckLogo({size=34}){return <img className="duck-logo-pic" src={duckFarmingLogo} width={size} height={size} alt="Duck Farming real duck logo"/>}
function App(){
 const [session,setSession]=useState(null),[profile,setProfile]=useState(null),[busy,setBusy]=useState(true),[error,setError]=useState('');
 const load=async s=>{setSession(s||null);if(!s){setProfile(null);return}try{const p=await call(supabase.rpc('get_my_profile'));setProfile(Array.isArray(p)?p[0]:p)}catch(e){setProfile(null);setError(err(e))}};
 useEffect(()=>{let live=true;(async()=>{try{if(!hasSupabaseKey)throw Error('Supabase configuration is missing.');const {data:{session:s}}=await supabase.auth.getSession();if(live)await load(s)}catch(e){if(live)setError(err(e))}finally{if(live)setBusy(false)}})();const {data:{subscription}}=supabase.auth.onAuthStateChange((_,s)=>{if(live)load(s)});return()=>{live=false;subscription.unsubscribe()}},[]);
 if(busy)return <><style>{premiumStyles}</style><div className="splash"><DuckLogo size={64}/><b>DUCK FARMING</b><span>Loading your secure farm…</span></div></>;
 if(!session)return <><style>{premiumStyles}</style><Auth error={error} setError={setError}/></>;
 if(!profile)return <><style>{premiumStyles}</style><div className="splash"><Notice type="error">{error||'Profile could not be loaded.'}</Notice><Btn onClick={()=>supabase.auth.signOut()}>Sign out</Btn></div></>;
 return <><style>{premiumStyles}</style><div className="df-luxury-app">{profile.role==='admin'?<Admin profile={profile} logout={()=>supabase.auth.signOut()}/>:<Customer profile={profile} logout={()=>supabase.auth.signOut()} />}</div></>
}
function Auth({error,setError}){const initialRef=useMemo(()=>{try{return new URLSearchParams(window.location.search).get('ref')?.trim().toUpperCase()||''}catch(_){return ''}},[]);const [mode,setMode]=useState(initialRef?'signup':'login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[phone,setPhone]=useState(''),[busy,setBusy]=useState(false);const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{if(mode==='login'){const {error:x}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(x)throw x}else{const {data,error:x}=await supabase.auth.signUp({email:email.trim(),password,options:{data:{full_name:name.trim(),phone:phone.trim(),referral_code:initialRef||null}}});if(x)throw x;if(data.user&&!data.session)setError('Account created. Check your email, then log in.')}}catch(e){setError(err(e))}finally{setBusy(false)}};return <main className="auth"><div className="auth-brand"><div className="logo"><DuckLogo/></div><small>PRIVATE DIGITAL FARM</small><h1>Grow a farm that works <em>every day.</em></h1><p>Buy productive ducks, receive scheduled eggs, earn referral rewards and request secure withdrawals.</p><div className="feature-row"><span>24h cycles</span><span>Premium dashboard</span><span>Secure payouts</span></div></div><Card className="auth-card"><div className="brand"><div className="logo"><DuckLogo/></div><div><b>Duck Farming</b><small>Premium digital farm</small></div></div><div className="tabs"><button type="button" className={mode==='login'?'active':''} onClick={()=>setMode('login')}>Login</button><button type="button" className={mode==='signup'?'active':''} onClick={()=>setMode('signup')}>Create account</button></div>{mode==='signup'&&initialRef&&<div className="ref-referred-banner"><Gift size={18}/><div><small>REFERRED BY</small><b>{initialRef}</b><span>Your referral ID was added automatically from the referral link.</span></div></div>}{error&&<Notice type="error">{error}</Notice>}<form onSubmit={submit}>{mode==='signup'&&<><Field label="Full name" value={name} onChange={e=>setName(e.target.value)} required/><Field label="Phone" value={phone} onChange={e=>setPhone(e.target.value)} required/></>}<Field label="Email" type="email" value={email} onChange={e=>setEmail(e.target.value)} required/><Field label="Password" type="password" minLength="6" value={password} onChange={e=>setPassword(e.target.value)} required/><Btn disabled={busy}>{busy?'Please wait…':mode==='login'?'Login securely':'Create account'}</Btn></form></Card></main>}

const customerNav=[['home','Home',Home],['buy','Buy Ducks',ShoppingBag],['deposit','Deposit',Receipt],['ducks','My Ducks',Bird],['wallet','Egg Wallet',Wallet],['ref','Referral Hub',Gift],['withdraw','Withdraw',Banknote],['profile','Profile',User]];
function Shell({children,profile,logout,admin=false}){const [tab,setTab]=useState(admin?'overview':'home'),[open,setOpen]=useState(false),[tick,setTick]=useState(0),[contact,setContact]=useState(null);const nav=admin?[['overview','Overview',Home],['ducks','Ducks',Bird],['deposits','Deposits',Receipt],['customers','Customers',Users],['referrals','Referral Commission',Gift],['payments','Payment Methods',CreditCard],['rates','Egg Prices',Banknote],['withdrawals','Withdrawals',Wallet],['settings','Admin Account',Settings]]:customerNav;useEffect(()=>{if(admin)return;call(supabase.from('site_settings').select('admin_phone,whatsapp_number,whatsapp_channel,whatsapp_details,site_name').eq('id',1).maybeSingle()).then(setContact).catch(()=>{})},[admin,tick]);const channelUrl='https://whatsapp.com/channel/0029Vb8SE9t29756Lhz37J2Y';return <div className="shell"><header><button className="hamb" onClick={()=>setOpen(!open)}><Menu/></button><div className="brand"><div className="logo"><DuckLogo/></div><div><b>Duck Farming</b><small>{admin?'ADMIN CONTROL':'Premium digital farm'}</small></div></div><div className="header-actions"><span className="chip"><User size={15}/>{profile.full_name||'Account'}</span><button className="icon" onClick={()=>setTick(tick+1)}><RefreshCw size={18}/></button><button className="icon" onClick={logout}><LogOut size={18}/></button></div></header>{!admin&&<div className="customer-contact-bar"><div className="contact-icon">WA</div><div><small>OFFICIAL SUPPORT</small><b>{contact?.whatsapp_details||'WhatsApp Support'}</b><span>{contact?.whatsapp_number||contact?.admin_phone||'Contact admin for assistance'}</span></div><div className="contact-actions">{contact?.whatsapp_number&&<a href={'https://wa.me/'+String(contact.whatsapp_number).replace(/[^0-9]/g,'')} target="_blank" rel="noopener noreferrer">WhatsApp</a>}<a href="https://whatsapp.com/channel/0029Vb8SE9t29756Lhz37J2Y" target="_blank" rel="noopener noreferrer">Follow WhatsApp Channel</a></div></div>}<div className="body"><aside className={open?'open':''}>{nav.map(([id,label,I])=><button key={id} className={tab===id?'active':''} onClick={()=>{setTab(id);setOpen(false)}}><I size={18}/><span>{label}</span><ChevronRight size={14}/></button>)}</aside><main>{children(tab,tick,setTab)}</main></div></div>}

function Customer({profile,logout}){return <Shell profile={profile} logout={logout}>{(tab,tick,setTab)=>{const common={profile,tick,go:setTab};switch(tab){case'buy':return <Buy {...common}/>;case'deposit':return <Deposit {...common}/>;case'ducks':return <MyDucks {...common}/>;case'wallet':return <WalletPage {...common}/>;case'ref':return <Referral {...common}/>;case'withdraw':return <Withdraw {...common}/>;case'profile':return <Profile {...common}/>;default:return <HomePage {...common}/>}}}</Shell>}


function EggTimer({lastEggAt,intervalHours=24,expired=false}){
  const [now,setNow]=useState(Date.now());
  useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(id)},[]);
  if(expired||!lastEggAt)return <span className="subline">Production inactive</span>;
  const next=new Date(new Date(lastEggAt).getTime()+Number(intervalHours||24)*3600000).getTime();
  const left=Math.max(0,next-now);
  const h=Math.floor(left/3600000),m=Math.floor((left%3600000)/60000),s=Math.floor((left%60000)/1000);
  return <span className="live-timer"><Clock3 size={15}/> Next egg in {String(h).padStart(2,'0')}:{String(m).padStart(2,'0')}:{String(s).padStart(2,'0')}</span>;
}

function EggBalanceBreakdown({markets=[],compact=false}){
 const duckMarkets=markets.filter(x=>x.market_type==='duck');
 const referral=markets.find(x=>x.market_type==='referral');
 const items=[
  ...duckMarkets.map(x=>({key:`duck-${x.duck_id}`,name:x.duck_name||'Duck',eggs:Math.max(0,Number(x.available_eggs||0)),type:'duck'})),
  ...(referral?[{key:'referral-earnings',name:'Referral Earnings',eggs:Math.max(0,Number(referral.available_eggs||0)),type:'referral'}]:[])
 ];
 if(!items.length)return <Card className="egg-balance-empty"><div className="empty">Your separate egg balances will appear here after you activate a duck or earn referral eggs.</div></Card>;
 return <div className={`egg-balance-grid ${compact?'compact':''}`}>
  {items.map(x=><Card className={`egg-balance-card ${x.type==='referral'?'referral-balance':''}`} key={x.key}>
   <div className="egg-balance-icon"><Egg size={22}/></div>
   <div className="egg-balance-info">
    <small>{x.type==='referral'?'REFERRAL EGGS':'DUCK EGGS'}</small>
    <h3>{x.name}</h3>
    <span>Balance: <b>{x.eggs} eggs</b></span>
   </div>
  </Card>)}
 </div>
}

